import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, convert, formatMoney, RATES } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(0.1 * 3 * 100), 30);
  assert.equal(roundCents(1.005 * 100), 100);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(-250), '-€2.50');
  assert.equal(formatEuros(100000000), '€1,000,000.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(100000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100000);
});

test('convert EUR to USD', () => {
  // 100 EUR cents = 1 EUR
  // 1 EUR × 1.085 = 1.085 USD = 108.5 USD cents → 108 or 109 cents (banker's rounding)
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 10000 * 1.085 = 10850, rounds to 10850
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  // 100 EUR cents = 1 EUR
  // 1 EUR × 0.8425 = 0.8425 GBP = 84.25 GBP cents → 84 cents (banker's rounding)
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 10000 * 0.8425 = 8425
  assert.equal(result.value, 8425);
});

test('convert handles larger amounts correctly', () => {
  // 1 million EUR cents = 10,000 EUR
  const resultUsd = convert(100000000, 'USD');
  assert.equal(resultUsd.ok, true);
  // 100000000 * 1.085 = 108500000
  assert.equal(resultUsd.value, 108500000);
});

test('convert returns error for unknown currency', () => {
  const result = convert(10000, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert handles zero amount', () => {
  const resultUsd = convert(0, 'USD');
  assert.equal(resultUsd.ok, true);
  assert.equal(resultUsd.value, 0);

  const resultGbp = convert(0, 'GBP');
  assert.equal(resultGbp.ok, true);
  assert.equal(resultGbp.value, 0);
});

test('convert applies rounding correctly', () => {
  // Test a value that would result in a .5 cent
  // 1 cent * 1.085 = 1.085 cents
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('formatMoney displays EUR with euro symbol', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
});

test('formatMoney displays USD with dollar sign', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
});

test('formatMoney displays GBP with pound sign', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
});

test('formatMoney handles negative amounts', () => {
  assert.equal(formatMoney(-123456, 'EUR'), '-€1,234.56');
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
});

test('formatMoney includes thousands separators', () => {
  assert.equal(formatMoney(100000000, 'EUR'), '€1,000,000.00');
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney pads cents correctly', () => {
  assert.equal(formatMoney(1, 'EUR'), '€0.01');
  assert.equal(formatMoney(10, 'USD'), '$0.10');
  assert.equal(formatMoney(100, 'GBP'), '£1.00');
});

test('convert and formatMoney work together', () => {
  // Convert 50 EUR to USD and format
  const cents = convert(5000, 'USD');
  assert.equal(cents.ok, true);
  const formatted = formatMoney(cents.value, 'USD');
  assert.equal(formatted, '$54.25'); // 5000 * 1.085 = 5425
});

test('convert EUR to USD and back', () => {
  const toUsd = convert(10000, 'USD');
  assert.equal(toUsd.ok, true);
  // 10000 * 1.085 = 10850 USD cents
  // 10850 / 1.085 ≈ 10000 EUR cents
  const backToEur = convert(toUsd.value, 'EUR');
  assert.equal(backToEur.ok, true);
  // Should be close to original due to rounding
  assert(Math.abs(backToEur.value - 10000) <= 1);
});

test('format various EUR amounts', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(99, 'EUR'), '€0.99');
  assert.equal(formatMoney(100, 'EUR'), '€1.00');
  assert.equal(formatMoney(1000, 'EUR'), '€10.00');
  assert.equal(formatMoney(10000, 'EUR'), '€100.00');
  assert.equal(formatMoney(100000, 'EUR'), '€1,000.00');
});
